-- ============================================================
-- GSO PRIMS — Sprint 11: Supabase schema
-- Run this whole file once in the Supabase SQL Editor.
-- Creates tables, RLS policies, audit triggers, document-number
-- RPC, storage bucket, realtime publication, and seed data.
-- ============================================================

-- ---------- tables ----------

create table public.suppliers (
  id text primary key,
  name text not null,
  address text not null,
  contact text not null,
  contact_person text,
  email text
);

create table public.purchase_requests (
  id text primary key,
  pr_number text unique not null,
  department_code text not null,
  requester text not null,
  purpose text not null,
  funding_source text not null,
  request_date date not null,
  status text not null,
  items jsonb not null default '[]',
  attachments jsonb not null default '[]',
  comments jsonb not null default '[]',
  history jsonb not null default '[]',
  approvals jsonb not null default '[]',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.purchase_orders (
  id text primary key,
  po_number text unique not null,
  pr_number text not null,
  department_code text not null,
  requester text not null,
  purpose text not null,
  supplier_id text not null,
  delivery_address text not null,
  expected_delivery date not null,
  issued_date date not null,
  status text not null,
  items jsonb not null default '[]',
  attachments jsonb not null default '[]',
  comments jsonb not null default '[]',
  history jsonb not null default '[]',
  approvals jsonb not null default '[]',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.ris_requests (
  id text primary key,
  ris_number text unique not null,
  pr_number text not null,
  po_number text,
  department_code text not null,
  requester text not null,
  purpose text not null,
  issued_by text not null,
  received_by text not null,
  issue_date date not null,
  status text not null,
  items jsonb not null default '[]',
  attachments jsonb not null default '[]',
  comments jsonb not null default '[]',
  history jsonb not null default '[]',
  approvals jsonb not null default '[]',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.inventory_items (
  id text primary key,
  item_code text unique not null,
  name text not null,
  category text not null,
  description text,
  unit text not null,
  location text not null,
  on_hand integer not null default 0,
  reorder_level integer not null default 0,
  critical_level integer not null default 0,
  supplier_id text not null,
  unit_price numeric not null default 0,
  attachments jsonb not null default '[]',
  comments jsonb not null default '[]',
  history jsonb not null default '[]',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.stock_card (
  id text primary key,
  date timestamptz not null default now(),
  document_number text not null,
  type text not null,
  item_id text not null,
  item_name text not null,
  quantity_in integer not null default 0,
  quantity_out integer not null default 0,
  balance integer not null,
  remarks text,
  user_name text not null
);

create table public.reservations (
  id text primary key,
  res_number text unique not null,
  facility_id text not null,
  department_code text not null,
  borrower text not null,
  contact_number text not null,
  purpose text not null,
  date date not null,
  start_time text not null,
  end_time text not null,
  equipment jsonb not null default '[]',
  status text not null,
  attachments jsonb not null default '[]',
  comments jsonb not null default '[]',
  history jsonb not null default '[]',
  approvals jsonb not null default '[]',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.audit_logs (
  id text primary key,
  timestamp timestamptz not null default now(),
  user_name text not null,
  user_role text not null default 'System',
  department_code text not null default 'GSO',
  module text not null,
  action text not null,
  document_number text,
  previous_value text,
  updated_value text,
  response text not null default '',
  remarks text,
  ip text not null default '—',
  browser text not null default '—',
  os text not null default '—',
  session_id text not null default '—',
  severity text not null default 'Information',
  status text not null default 'Success',
  comments jsonb not null default '[]'
);

create table public.doc_counters (
  prefix text primary key,
  next_no integer not null
);

create index idx_pr_status on public.purchase_requests (status);
create index idx_pr_dept on public.purchase_requests (department_code);
create index idx_po_status on public.purchase_orders (status);
create index idx_ris_status on public.ris_requests (status);
create index idx_stock_item on public.stock_card (item_id);
create index idx_res_slot on public.reservations (facility_id, date);
create index idx_audit_time on public.audit_logs (timestamp desc);
create index idx_audit_doc on public.audit_logs (document_number);
create index idx_audit_session on public.audit_logs (session_id);

-- ---------- document numbering RPC ----------

create or replace function public.next_doc_number(p_prefix text)
returns integer
language sql
security definer
set search_path = public
as $$
  update public.doc_counters
     set next_no = next_no + 1
   where prefix = p_prefix
  returning next_no - 1;
$$;

grant execute on function public.next_doc_number(text) to anon, authenticated;

-- ---------- audit trigger (every mutation is logged) ----------

create sequence public.audit_id_seq start 1000;

create or replace function public.log_audit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_new jsonb := case when tg_op = 'DELETE' then null else to_jsonb(new) end;
  v_old jsonb := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  v_ref jsonb := coalesce(v_new, v_old);
  v_doc text := coalesce(
    v_ref->>'pr_number', v_ref->>'po_number', v_ref->>'ris_number',
    v_ref->>'res_number', v_ref->>'item_code', v_ref->>'id');
  v_module text := case tg_table_name
    when 'purchase_requests' then 'Purchase Requests'
    when 'purchase_orders' then 'Purchase Orders'
    when 'ris_requests' then 'RIS'
    when 'inventory_items' then 'Inventory'
    when 'reservations' then 'Reservations'
    else 'System' end;
  v_action text := case tg_op
    when 'INSERT' then 'Record Created'
    when 'UPDATE' then 'Record Updated'
    else 'Record Deleted' end;
  v_user text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'email',
    'Public Portal');
begin
  insert into public.audit_logs
    (id, timestamp, user_name, user_role, department_code, module, action,
     document_number, previous_value, updated_value, response, severity, status, session_id)
  values (
    'AUD-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.audit_id_seq')::text, 4, '0'),
    now(), v_user,
    case when v_user = 'Public Portal' then 'Public Portal' else 'Authenticated User' end,
    'GSO', v_module, v_action, v_doc,
    case when v_old is null then null else 'Status: ' || coalesce(v_old->>'status', '—') end,
    case when v_new is null then '—' else 'Status: ' || coalesce(v_new->>'status', '—') end,
    v_action || ' via GSO PRIMS',
    case when tg_op = 'DELETE' then 'Critical' else 'Information' end,
    'Success', 'SES-DB');
  return coalesce(new, old);
end;
$$;

-- (audit triggers are attached after seeding, at the end of this file)

-- ---------- row level security ----------

alter table public.suppliers enable row level security;
alter table public.purchase_requests enable row level security;
alter table public.purchase_orders enable row level security;
alter table public.ris_requests enable row level security;
alter table public.inventory_items enable row level security;
alter table public.stock_card enable row level security;
alter table public.reservations enable row level security;
alter table public.audit_logs enable row level security;
alter table public.doc_counters enable row level security;

-- Administrators (authenticated) get full access everywhere.
create policy auth_all_suppliers on public.suppliers for all to authenticated using (true) with check (true);
create policy auth_all_pr on public.purchase_requests for all to authenticated using (true) with check (true);
create policy auth_all_po on public.purchase_orders for all to authenticated using (true) with check (true);
create policy auth_all_ris on public.ris_requests for all to authenticated using (true) with check (true);
create policy auth_all_inv on public.inventory_items for all to authenticated using (true) with check (true);
create policy auth_all_stock on public.stock_card for all to authenticated using (true) with check (true);
create policy auth_all_res on public.reservations for all to authenticated using (true) with check (true);
create policy auth_all_audit on public.audit_logs for all to authenticated using (true) with check (true);
create policy auth_all_counters on public.doc_counters for all to authenticated using (true) with check (true);

-- Public portal (anon): read for tracking/wizards, insert for submissions.
create policy anon_read_pr on public.purchase_requests for select to anon using (true);
create policy anon_read_po on public.purchase_orders for select to anon using (true);
create policy anon_read_ris on public.ris_requests for select to anon using (true);
create policy anon_read_res on public.reservations for select to anon using (true);
create policy anon_read_inv on public.inventory_items for select to anon using (true);
create policy anon_read_suppliers on public.suppliers for select to anon using (true);
create policy anon_insert_pr on public.purchase_requests for insert to anon with check (true);
create policy anon_insert_ris on public.ris_requests for insert to anon with check (true);
create policy anon_insert_res on public.reservations for insert to anon with check (true);
create policy anon_counters on public.doc_counters for update to anon using (true) with check (true);
create policy anon_counters_read on public.doc_counters for select to anon using (true);

-- ---------- storage ----------

insert into storage.buckets (id, name, public) values ('attachments', 'attachments', true);

create policy attachments_read on storage.objects for select using (bucket_id = 'attachments');
create policy attachments_insert_auth on storage.objects for insert to authenticated with check (bucket_id = 'attachments');
create policy attachments_insert_anon on storage.objects for insert to anon with check (bucket_id = 'attachments');
create policy attachments_delete_auth on storage.objects for delete to authenticated using (bucket_id = 'attachments');

-- ---------- realtime ----------

alter publication supabase_realtime add table
  public.purchase_requests, public.purchase_orders, public.ris_requests,
  public.inventory_items, public.stock_card, public.reservations, public.audit_logs;

