-- ---------- attach audit triggers (after seeding, so seeds don't generate log noise) ----------

create trigger audit_purchase_requests after insert or update or delete on public.purchase_requests
  for each row execute function public.log_audit();
create trigger audit_purchase_orders after insert or update or delete on public.purchase_orders
  for each row execute function public.log_audit();
create trigger audit_ris_requests after insert or update or delete on public.ris_requests
  for each row execute function public.log_audit();
create trigger audit_inventory_items after insert or update or delete on public.inventory_items
  for each row execute function public.log_audit();
create trigger audit_reservations after insert or update or delete on public.reservations
  for each row execute function public.log_audit();
